//! System statistics — CPU, memory, disks, processes, uptime.
//!
//! Backed by `sysinfo`, which keeps an internal snapshot that callers
//! refresh selectively. We hold a single process-wide `System` instance
//! behind a mutex so the snapshot persists across calls (required for
//! CPU-usage deltas to be meaningful — the first refresh always reports
//! 0% because there's no baseline).
//!
//! Disks live in their own `Disks` collection (sysinfo 0.32 split system
//! data from disk/network), recomputed on each call since they're cheap.
//!
//! Dispatch is generated by `#[tynd::handler]` (U10).

use std::sync::LazyLock;

use parking_lot::Mutex;
use serde_json::{json, Value};
use smallvec::SmallVec;
use sysinfo::{Disks, ProcessRefreshKind, RefreshKind, System};

use crate::tynd;

/// Marker for the `#[tynd::handler]` dispatch table — sysinfo state
/// lives in the file-level `SYS` static.
#[derive(Debug, Default)]
pub struct SystemStatsApi;

#[tynd::handler(api = "systemStats")]
impl SystemStatsApi {
    /// Aggregate CPU usage (%) plus core count and brand string.
    /// Usage is the mean across logical CPUs since the previous
    /// `cpu()` snapshot — the first call always reports 0% because
    /// sysinfo needs two refreshes to compute a delta.
    pub fn cpu() -> Value {
        cpu_impl()
    }

    /// Total / used / free physical and swap memory, in bytes.
    pub fn memory() -> Value {
        memory_impl()
    }

    /// Per-mount disk stats: total/available bytes and filesystem
    /// type. Recomputed on every call (cheap on every supported OS).
    pub fn disks() -> Value {
        disks_impl()
    }

    /// Paginated process listing sorted by ascending PID. `limit`
    /// defaults to 50 and is capped at 1000; `offset` skips from the
    /// front of the list.
    pub fn processes(limit: Option<u64>, offset: Option<u64>) -> Value {
        let limit = limit.unwrap_or(50).min(1000) as usize;
        let offset = offset.unwrap_or(0) as usize;
        processes_impl(limit, offset)
    }

    /// Host uptime in seconds (`{ "seconds": u64 }`).
    pub fn uptime() -> Value {
        json!({ "seconds": System::uptime() })
    }
}

/// Process-wide `System` snapshot. sysinfo computes CPU usage as a
/// delta between two refreshes — re-instantiating per call always
/// reports 0%. The mutex is short-lived (refresh + read) so contention
/// stays bounded even under concurrent OS calls. `LazyLock` builds the
/// `System` once on first access.
static SYS: LazyLock<Mutex<System>> =
    LazyLock::new(|| Mutex::new(System::new_with_specifics(RefreshKind::new())));

fn cpu_impl() -> Value {
    let mut s = SYS.lock();
    s.refresh_cpu_usage();
    let cpus = s.cpus();
    // Aggregate usage = mean across logical CPUs. Per-core breakdown
    // would change the API shape; callers that want it can iterate
    // with a future `cpuPerCore()` method.
    let count = cpus.len();
    let usage = if count == 0 {
        0.0_f32
    } else {
        cpus.iter().map(sysinfo::Cpu::cpu_usage).sum::<f32>() / count as f32
    };
    let brand = cpus
        .first()
        .map(|c| c.brand().to_string())
        .unwrap_or_default();
    json!({
        "usage": usage,
        "count": count,
        "brand": brand,
    })
}

fn memory_impl() -> Value {
    let mut s = SYS.lock();
    s.refresh_memory();
    let total = s.total_memory();
    let used = s.used_memory();
    json!({
        "total": total,
        "used": used,
        "free": total.saturating_sub(used),
        "swap_total": s.total_swap(),
        "swap_used": s.used_swap(),
    })
}

fn disks_impl() -> Value {
    let disks = Disks::new_with_refreshed_list();
    let arr: Vec<Value> = disks
        .iter()
        .map(|d| {
            json!({
                "name": d.name().to_string_lossy(),
                "mount": d.mount_point().to_string_lossy(),
                "total": d.total_space(),
                "available": d.available_space(),
                "fs_type": d.file_system().to_string_lossy(),
            })
        })
        .collect();
    Value::Array(arr)
}

fn processes_impl(limit: usize, offset: usize) -> Value {
    let mut s = SYS.lock();
    s.refresh_processes_specifics(
        sysinfo::ProcessesToUpdate::All,
        true,
        ProcessRefreshKind::new().with_cpu().with_memory(),
    );

    // Stable order = ascending PID. sysinfo's `processes()` returns a
    // HashMap; sort once then page. Use a `SmallVec` with a 64-PID inline
    // capacity so dev machines / lightly loaded boxes never spill to the
    // heap; busier hosts (>64 procs) transparently fall back to heap.
    let mut pids: SmallVec<[&sysinfo::Pid; 64]> = s.processes().keys().collect();
    pids.sort();

    let arr: Vec<Value> = pids
        .into_iter()
        .skip(offset)
        .take(limit)
        .filter_map(|pid| {
            let p = s.processes().get(pid)?;
            Some(json!({
                "pid": pid.as_u32(),
                "name": p.name().to_string_lossy(),
                "cpu": p.cpu_usage(),
                "memory": p.memory(),
                "parent_pid": p.parent().map(sysinfo::Pid::as_u32),
            }))
        })
        .collect();
    Value::Array(arr)
}
